add_filter( 'woocommerce_product_single_add_to_cart_text', 'perfectpixel_rename_atc_single', 20, 2 );
add_filter( 'woocommerce_product_add_to_cart_text', 'perfectpixel_rename_atc_loop', 20, 2 );

function perfectpixel_rename_atc_single( $text, $product ) {
	return ( $product && $product->is_type( 'external' ) ) ? $text : '{{atc_single_label}}';
}

function perfectpixel_rename_atc_loop( $text, $product ) {
	if ( $product && $product->is_type( 'simple' ) && $product->is_purchasable() && $product->is_in_stock() ) {
		return '{{atc_loop_label}}';
	}
	return $text;
}
